  /** floor height of the landmark set pieces at (x,z); null when (x,z) is not on one of them. Colliders tagged floor|stair|step carry GT.onfoot already — this is for NPC placement / vehicles. */
  function groundHeight(x, z) { const c = CK, B = RL.B;
    if (x >= 22.5 && x <= 37.5 && z >= 135.6 && z < 138.0) return Math.min(c.F, .3 + .15 * Math.floor((z - 135.6) / .4)); if (x >= 22.3 && x <= 37.7 && z >= 138 && z < c.ZS) return c.F;
    if (x > c.X0 && x < c.X1 && z >= c.ZS && z < c.ZN) { if (x < c.WB) return c.G; if (z > 149.1 && x < 32.4) return c.F + clamp(Math.ceil((32.4 - x) / .3), 0, 28) * .15; return c.F; }
    if (x > B.x1 && x < B.x1 + 1.52 && Math.abs(z) < 3.5) return .6 - .15 * (x < B.x1 + .5 ? 0 : 1 + Math.floor((x - B.x1 - .5) / .34)); if (x > 122 && x < 143 && z > -43.6 && z < -24.4) return .05; return null; }
