    if (isTrain) P.push([GT.mat('metal_dark', { color: 0x2b2f34 }), 0x2b2f34], [GT.mat('plastic_black', { rough: .12 }), 0x0c0d10], [M.galv, 0x9da3a8]);
    const geos = []; for (const [m, hex] of P) { const mesh = grp.children.find(c => c.material === m); if (!mesh) continue; const uv = A.add('sw' + hex, 24, 24, (g, w, h) => { g.fillStyle = '#' + ('000000' + hex.toString(16)).slice(-6); g.fillRect(0, 0, w, h); }), u = mesh.geometry.attributes.uv, cu = (uv[0] + uv[2]) / 2, cv2 = (uv[1] + uv[3]) / 2; for (let i = 0; i < u.count; i++) u.setXY(i, cu, cv2); geos.push(mesh.geometry); grp.remove(mesh); }
